use crate::state::ReportedState;
use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::{collections::BTreeMap, time::Instant};

#[derive(Clone, Default, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct CommandProfile {
    pub evidence: String,
    pub commands: BTreeMap<String, VerifiedCommand>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub operator_recovery: Option<OperatorRecovery>,
}
/// Temporary, operator-created admission. It is never generated by HA or MQTT.
#[derive(Clone, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct OperatorRecovery {
    pub room_id: u64,
    pub expires_unix_seconds: u64,
}
impl OperatorRecovery {
    pub fn current(&self) -> bool {
        self.room_id <= 255
            && std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .is_ok_and(|now| now.as_secs() < self.expires_unix_seconds)
    }
}
#[derive(Clone, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct VerifiedCommand {
    pub params: Value,
    #[serde(default)]
    pub expected_robot_status: Vec<u64>,
    pub expected_docked: Option<bool>,
    #[serde(default)]
    pub rooms_supported: bool,
    #[serde(default)]
    pub source_states: Vec<StatePredicate>,
    #[serde(default)]
    pub no_op_states: Vec<StatePredicate>,
    #[serde(default)]
    pub feedback_states: Vec<StatePredicate>,
}
/// An exact, qualified tuple. No wildcard or inferred status-code meanings.
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct StatePredicate {
    pub robot_status: u16,
    pub work_status: u16,
    pub station_contact: bool,
    pub error_code: u16,
}
impl StatePredicate {
    pub fn from_status(status: &Value) -> Option<Self> {
        Some(Self {
            robot_status: u16::try_from(status.get("robot_status")?.as_u64()?).ok()?,
            work_status: u16::try_from(status.get("work_status")?.as_u64()?).ok()?,
            station_contact: status.get("station_contact")?.as_bool()?,
            error_code: u16::try_from(status.get("error_code")?.as_u64()?).ok()?,
        })
    }
}
pub enum Decision {
    NoOp,
    Send(Value),
}
pub fn mop_settings_required(profile: &CommandProfile) -> bool {
    profile.commands.get("start").is_some_and(|command| {
        command.rooms_supported && command.params.get("cmd") == Some(&serde_json::json!(5))
    })
}
pub fn eligible(profile: &CommandProfile, name: &str) -> bool {
    if profile.evidence.trim().is_empty()
        || ![
            "start",
            "pause",
            "stop",
            "return_to_base",
            "resume",
            "end_task",
            "vacuum_end_task",
            "vacuum_start",
            "vacuum_resume",
        ]
        .contains(&name)
    {
        return false;
    }
    let Some(command) = profile.commands.get(name) else {
        return false;
    };
    let Some(params) = command.params.as_object() else {
        return false;
    };
    if params.get("cmd").and_then(Value::as_u64).is_none()
        || params.len() > 16
        || serde_json::to_vec(params).map_or(true, |encoded| encoded.len() > 4096)
    {
        return false;
    }
    if name == "resume" && (params.len() != 1 || params.get("cmd") != Some(&serde_json::json!(3))) {
        return false;
    }
    if ["end_task", "vacuum_end_task"].contains(&name) {
        let source = StatePredicate {
            robot_status: if name == "vacuum_end_task" { 301 } else { 303 },
            work_status: 0,
            station_contact: true,
            error_code: 0,
        };
        let idle = StatePredicate {
            robot_status: 100,
            work_status: 0,
            station_contact: true,
            error_code: 0,
        };
        if params.len() != 1
            || params.get("cmd") != Some(&serde_json::json!(4))
            || command.rooms_supported
            || command.source_states != [source]
            || command.no_op_states != [idle.clone()]
            || command.feedback_states != [idle]
        {
            return false;
        }
    }
    if name == "vacuum_start" {
        let idle = StatePredicate {
            robot_status: 100,
            work_status: 0,
            station_contact: true,
            error_code: 0,
        };
        let floor = StatePredicate {
            robot_status: 300,
            work_status: 1,
            station_contact: false,
            error_code: 0,
        };
        if params.len() != 3
            || params.get("cmd") != Some(&serde_json::json!(5))
            || !params.get("clean_order").is_some_and(Value::is_array)
            || params.get("floor_type") != Some(&serde_json::json!([]))
            || !command.rooms_supported
            || command.source_states != [idle]
            || command.no_op_states != [floor.clone()]
            || command.feedback_states != [floor]
        {
            return false;
        }
    }
    if name == "vacuum_resume" {
        let stopped = StatePredicate {
            robot_status: 300,
            work_status: 0,
            station_contact: false,
            error_code: 3001,
        };
        let floor = StatePredicate {
            robot_status: 300,
            work_status: 1,
            station_contact: false,
            error_code: 0,
        };
        if params.len() != 1
            || params.get("cmd") != Some(&serde_json::json!(5))
            || command.rooms_supported
            || command.source_states != [stopped]
            || command.no_op_states != [floor.clone()]
            || command.feedback_states != [floor]
        {
            return false;
        }
    }
    let sets = [
        &command.source_states,
        &command.no_op_states,
        &command.feedback_states,
    ];
    if sets.iter().any(|states| {
        states.is_empty()
            || states.len() > 64
            || states
                .iter()
                .enumerate()
                .any(|(n, state)| states[..n].contains(state))
            || (["start", "resume"].contains(&name) && states.iter().any(|s| s.error_code != 0))
    }) {
        return false;
    }
    if command
        .source_states
        .iter()
        .any(|s| command.no_op_states.contains(s))
        || command.feedback_states.iter().any(|s| {
            !command.no_op_states.contains(s)
                || (!command.expected_robot_status.is_empty()
                    && !command
                        .expected_robot_status
                        .contains(&u64::from(s.robot_status)))
                || command
                    .expected_docked
                    .is_some_and(|docked| docked != s.station_contact)
        })
        || (name == "return_to_base" && command.source_states.iter().any(|s| s.station_contact))
    {
        return false;
    }
    true
}
pub fn decide(
    profile: &CommandProfile,
    input: &CommandInput,
    state: &StatePredicate,
    rooms: &[u64],
) -> Result<Decision, String> {
    if !eligible(profile, &input.command) {
        return Err("command_guards_unverified".into());
    }
    let command = &profile.commands[&input.command];
    let mut params = command
        .params
        .as_object()
        .expect("eligible parameters")
        .clone();
    if let Some(plan) = &input.mop {
        if !["start", "vacuum_start"].contains(&input.command.as_str())
            || !input.rooms.is_empty()
            || !command.rooms_supported
            || params.get("cmd") != Some(&serde_json::json!(5))
            || params.len() != 3
            || !params.contains_key("clean_order")
            || !params.contains_key("floor_type")
        {
            return Err("mop_plan_invalid".into());
        }
        let (order, floor) = plan.wire(rooms)?;
        let floor = if input.command == "vacuum_start" {
            // Keep the required field while omitting mop dampness.
            vec![]
        } else {
            floor
        };
        params.insert("clean_order".into(), serde_json::json!(order));
        params.insert("floor_type".into(), serde_json::json!(floor));
    } else if !input.rooms.is_empty() {
        if input.command != "start"
            || !command.rooms_supported
            || input.rooms.len() > 64
            || input.rooms.iter().any(|r| !rooms.contains(r))
            || input
                .rooms
                .iter()
                .collect::<std::collections::BTreeSet<_>>()
                .len()
                != input.rooms.len()
        {
            return Err("room_selection_invalid".into());
        }
        params.insert("clean_order".into(), serde_json::json!(input.rooms));
        params.insert("floor_type".into(), serde_json::json!([]));
    }
    if command.no_op_states.contains(state) {
        if !input.rooms.is_empty() || input.mop.is_some() {
            return Err("room_selection_state_unverified".into());
        }
        return Ok(Decision::NoOp);
    }
    if !command.source_states.contains(state) {
        return Err("command_source_state_refused".into());
    }
    Ok(Decision::Send(Value::Object(params)))
}
#[derive(Clone, Debug, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct CommandInput {
    pub command: String,
    #[serde(default)]
    pub rooms: Vec<u64>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mop: Option<crate::plan::MopPlan>,
}
#[derive(Clone, Debug)]
pub enum LocalInput {
    Command(CommandInput),
    SelectRoom(String),
    SetPasses(u8),
    SetDampness(crate::plan::Dampness),
}
#[derive(Clone, Debug, PartialEq, Eq, Deserialize, Serialize)]
#[serde(deny_unknown_fields)]
pub struct MopContext {
    pub clean_mode: u16,
    pub main_task: u16,
    pub task_queue_empty: bool,
}
impl MopContext {
    pub fn from_status(status: &Value) -> Option<Self> {
        Some(Self {
            clean_mode: u16::try_from(status.get("clean_mode")?.as_u64()?).ok()?,
            main_task: u16::try_from(status.get("main_task")?.as_u64()?).ok()?,
            task_queue_empty: status.get("task_queue")?.as_array()?.is_empty(),
        })
    }
    pub fn idle_mop(&self) -> bool {
        self.clean_mode == 3 && self.main_task == 0 && self.task_queue_empty
    }
    pub fn active_mop(&self) -> bool {
        self.clean_mode == 3 && self.main_task == 1
    }
    pub fn idle_vacuum(&self) -> bool {
        self.clean_mode == 2 && self.main_task == 0 && self.task_queue_empty
    }
    pub fn active_vacuum(&self) -> bool {
        self.clean_mode == 2 && self.main_task == 1
    }
}
pub async fn dispatch_commands<T, F, Fut>(mut rx: tokio::sync::mpsc::Receiver<T>, run: F)
where
    F: Fn(T) -> Fut,
    Fut: std::future::Future<Output = ()>,
{
    while let Some(command) = rx.recv().await {
        let action = run(command);
        tokio::pin!(action);
        loop {
            tokio::select! {
                _=&mut action=>{
                    while rx.try_recv().is_ok() {}
                    break;
                }
                extra=rx.recv()=>{
                    if extra.is_none() {action.await;return;}
                }
            }
        }
    }
}
/// Preserve setting changes, but never queue another movement behind one in flight.
pub async fn dispatch_local<F, Fut>(mut rx: tokio::sync::mpsc::Receiver<LocalInput>, run: F)
where
    F: Fn(LocalInput) -> Fut,
    Fut: std::future::Future<Output = ()>,
{
    while let Some(input) = rx.recv().await {
        if !matches!(input, LocalInput::Command(_)) {
            run(input).await;
            continue;
        }
        let action = run(input);
        tokio::pin!(action);
        loop {
            tokio::select! {
                _ = &mut action => {
                    while let Ok(extra) = rx.try_recv() {
                        if !matches!(extra, LocalInput::Command(_)) {
                            run(extra).await;
                        }
                    }
                    break;
                }
                extra = rx.recv() => match extra {
                    Some(LocalInput::Command(_)) => {},
                    Some(setting) => run(setting).await,
                    None => { action.await; return; }
                }
            }
        }
    }
}
pub fn prepare(
    profile: &CommandProfile,
    input: &CommandInput,
    state: &ReportedState,
    rooms: &[u64],
    now: Instant,
) -> Result<Value, String> {
    if !state.fresh(now) {
        return Err("robot_status_stale".into());
    }
    let status = state
        .status
        .as_ref()
        .and_then(StatePredicate::from_status)
        .ok_or("command_state_missing")?;
    match decide(profile, input, &status, rooms)? {
        Decision::Send(params) => Ok(params),
        Decision::NoOp => Err("no_action_needed".into()),
    }
}


